test_that("MV17-G full calibration closure is aggregate-only and exact", {
  root<-testthat::test_path("..","..");a<-file.path(root,"docs","audits","mv17g-full-calibration-closure-v1");skip_if_not(dir.exists(a),"MV17-G calibration closure absent");r<-function(n)read.csv(file.path(a,n),stringsAsFactors=FALSE,check.names=FALSE);v<-r("mv17g-validation.csv");e<-r("mv17g-aggregate-empirical-calibration.csv");d<-r("mv17g-decision.csv");m<-r("mv17g-artifact-manifest.csv");expect_equal(nrow(v),26L);expect_true(all(v$passed));expect_equal(nrow(e),56L);expect_false(any(c("unit_id","unit_order","observed_value")%in%names(e)));expect_true(d$full_H0_H1_calibration_closed);expect_true(d$real_localization_prefreeze_eligible);expect_false(d$real_localization_authorized);files<-file.path(a,m$artifact);expect_equal(as.numeric(file.info(files)$size),m$bytes);expect_equal(unname(vapply(files,digest::digest,character(1L),algo="sha256",file=TRUE,serialize=FALSE)),unname(m$sha256))
})
